def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    L=None
    for r,row in enumerate(g):
        if row and all(x==2 for x in row): L=r
    srcs=[(r,c) for r in range(H) for c in range(W) if g[r][c]==4]
    for r,c in srcs:
        out[r][c]=0
        if r<L:
            for k in range(0,L-r):
                rr=L-1-k
                for cc in (c-k,c+k):
                    if 0<=rr<H and 0<=cc<W: out[rr][cc]=4
        elif r>L:
            for k in range(0,r-L):
                rr=L+1+k
                for cc in (c-k,c+k):
                    if 0<=rr<H and 0<=cc<W: out[rr][cc]=4
    return out

